ValidationRule.errorConditionFormula:
AND( OR( CONTAINS(UPPER(CondicaoPagamento__r.descricao__c), "MAIS PAY"), CONTAINS(TEXT(FormaDePagamento__c), "MP - MPAY") ), OR( NOT(CONTAINS(UPPER(CondicaoPagamento__r.descricao__c), "MAIS PAY")), NOT(CONTAINS(TEXT(FormaDePagamento__c), "MP - MPAY")) )
,OR(ISNEW(),ISCHANGED(CondicaoPagamento__c), ISCHANGED(FormaDePagamento__c))
)
